import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import styles from './Communities.module.css'; // Общие стили

// Компонент для отображения превью поста
const MiniPost = ({ post }) => {
    if (!post) return <div className={styles.noPost}>В этом сообществе пока нет постов</div>;
    
    return (
        <div className={styles.miniPost}>
            <div className={styles.miniPostHeader}>
                <span className={styles.lastPostLabel}>Последний пост:</span>
            </div>
            <div className={styles.miniPostContent}>
                {post.text && <p className={styles.miniPostText}>{post.text.slice(0, 100)}...</p>}
                {post.image && <img src={post.image} alt="post attachment" className={styles.miniPostImage} />}
            </div>
        </div>
    );
};

const CommunityCard = ({ community }) => {
    const navigate = useNavigate();
    const [isMember, setIsMember] = useState(false);
    const [lastPost, setLastPost] = useState(null);
    const [loadingPost, setLoadingPost] = useState(true);

    // Проверяем, подписан ли текущий юзер (нужно сравнить ID)
    useEffect(() => {
        // TODO: Получи ID текущего юзера из контекста или localStorage
        // Пока сделаем простую проверку, если member_id есть в списке (если бэк отдает список ID)
        // Для MVP можно просто хранить локальное состояние, если бэк не отдает is_member
        // Здесь предполагается, что мы пока просто управляем кнопкой
    }, []);

    // Загружаем последний пост для этой группы
    useEffect(() => {
        const fetchLastPost = async () => {
            try {
                // Запрашиваем посты этого сообщества
                const resp = await axios.get(`http://10.124.215.133:8000/api/posts/?community=${community.id}&limit=1`, {
                    headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
                });
                
                // Берем первый пост из списка (если пагинация, то results[0])
                const posts = resp.data.results || resp.data;
                if (posts.length > 0) {
                    setLastPost(posts[0]);
                }
            } catch (err) {
                console.error("Не удалось загрузить пост:", err);
            } finally {
                setLoadingPost(false);
            }
        };
        fetchLastPost();
    }, [community.id]);

    const handleJoin = async (e) => {
        e.stopPropagation(); // Чтобы не сработал клик по карточке
        try {
            await axios.post(`http://10.124.215.133:8000/api/communities/${community.id}/join/`, {}, {
                headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
            });
            setIsMember(true);
        } catch (err) {
            console.error("Ошибка подписки", err);
        }
    };

    const handleLeave = async (e) => {
        e.stopPropagation();
        try {
            await axios.post(`http://10.124.215.133:8000/api/communities/${community.id}/leave/`, {}, {
                headers: { 'Authorization': `Bearer ${localStorage.getItem('access')}` }
            });
            setIsMember(false);
        } catch (err) {
            console.error("Ошибка отписки", err);
        }
    };


    return (
        <div className={styles.card} onClick={() => navigate(`/communities/${community.id}`)}>
            <div className={styles.cardHeader}>
                <img 
                    src={community.avatar || "/images/community_placeholder.svg"} 
                    alt="avatar" 
                    className={styles.avatar}
                    onError={(e) => {e.target.src="/images/community_placeholder.svg"}} 
                />
                <div className={styles.info}>
                    <h3 className={styles.name}>{community.title}</h3>
                    <p className={styles.members}>{community.members_count} участников</p>
                </div>
                
                <button 
                    className={isMember ? styles.btnLeave : styles.btnJoin}
                    onClick={isMember ? handleLeave : handleJoin}
                >
                    {isMember ? "Выйти" : "Вступить"}
                </button>
            </div>

            <div className={styles.cardBody}>
                {loadingPost ? (
                    <div className={styles.skeletonText}>Загрузка поста...</div>
                ) : (
                    <MiniPost post={lastPost} />
                )}
            </div>
        </div>
    );
};

export default CommunityCard;
